class Solution {
  public int minOperations(int[] nums) {
    int n = nums.length;
    // state id: type * n + t ; type 0: nums[i] = (i + t) % n, type 1: nums[i] = (t - i) mod n
    int[] dist = new int[2 * n];
    java.util.Arrays.fill(dist, -1);
    java.util.ArrayDeque<Integer> queue = new java.util.ArrayDeque<>();
    int t0 = nums[0];
    boolean type0 = true, type1 = true;
    for (int i = 0; i < n; i++) {
      if (nums[i] != (i + t0) % n) type0 = false;
      if (nums[i] != ((t0 - i) % n + n) % n) type1 = false;
    }
    if (!type0 && !type1) return -1;
    if (type0) {
      dist[t0] = 0;
      queue.add(t0);
    }
    if (type1) {
      dist[n + t0] = 0;
      queue.add(n + t0);
    }
    while (!queue.isEmpty()) {
      int u = queue.poll();
      int type = u / n, t = u % n;
      if (type == 0 && t == 0) return dist[u];
      int rotated = type == 0 ? (t + 1) % n : (t - 1 + n) % n;
      int rot = type * n + rotated;
      int reversed = type == 0 ? n + (t - 1 + n) % n : (t + 1) % n;
      for (int v : new int[] {rot, reversed}) {
        if (dist[v] < 0) {
          dist[v] = dist[u] + 1;
          queue.add(v);
        }
      }
    }
    return -1;
  }
}
